import{_ as a,o,c as r,a2 as s}from"./chunks/framework.BXA5Pi9t.js";const m=JSON.parse('{"title":"56 Weeks Later- Becoming a Jack of All Trades","description":"","frontmatter":{"title":"56 Weeks Later- Becoming a Jack of All Trades","date":"2025-06-24T00:00:00.000Z","updated":"2025-06-24T00:00:00.000Z","tags":["Ceph","Crimson OSD","Performance Optimization","Distributed Storage","Storage Architecture"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2025/56_Weeks_Later_-_Becoming_a_Jack_of_All_Trades.md","filePath":"posts/2025/56_Weeks_Later_-_Becoming_a_Jack_of_All_Trades.md","lastUpdated":1780459816000}'),t={name:"posts/2025/56_Weeks_Later_-_Becoming_a_Jack_of_All_Trades.md"};function l(i,e,n,c,d,_){return o(),r("div",null,[...e[0]||(e[0]=[s('<h3 id="_56-weeks-later-becoming-a-jack-of-all-trades" tabindex="-1">56 Weeks Later- Becoming a Jack of All Trades <a class="header-anchor" href="#_56-weeks-later-becoming-a-jack-of-all-trades" aria-label="Permalink to &quot;56 Weeks Later- Becoming a Jack of All Trades&quot;">​</a></h3><p><strong>会议主题</strong>：Crimson OSD 架构性能测试进展与贡献回顾 <strong>主讲人</strong>：Ian Palos Perez（IBM SEF 团队成员） <strong>日期</strong>：近期会议</p><h4 id="核心讨论内容" tabindex="-1">核心讨论内容 <a class="header-anchor" href="#核心讨论内容" aria-label="Permalink to &quot;核心讨论内容&quot;">​</a></h4><h5 id="crimson-osd-架构概述" tabindex="-1">Crimson OSD 架构概述 <a class="header-anchor" href="#crimson-osd-架构概述" aria-label="Permalink to &quot;Crimson OSD 架构概述&quot;">​</a></h5><ul><li><strong>传统 Classic OSD</strong>：多线程架构，依赖线程间同步原语（如互斥锁）共享资源，包括 <code>messenger</code>、<code>PG</code>（Placement Groups）、<code>ObjectStore</code>。</li><li><strong>Crimson OSD</strong>：基于 <code>seastar</code> 框架，采用异步通信与同步计算模型，使用 C++20 特性，单 <code>reactor</code> 绑定单 CPU 核心，避免显式锁和资源共享。</li></ul><h5 id="性能测试结果" tabindex="-1">性能测试结果 <a class="header-anchor" href="#性能测试结果" aria-label="Permalink to &quot;性能测试结果&quot;">​</a></h5><ul><li><strong>随机读写性能</strong>：Crimson 在随机读性能上显著优于 Classic，但在随机写性能上仍有优化空间。</li><li><strong>Reactor 配置</strong>：测试了单 <code>reactor</code> 与双 <code>reactor</code> 绑定核心的策略，性能差异与工作负载相关。</li></ul><h5 id="关键贡献" tabindex="-1">关键贡献 <a class="header-anchor" href="#关键贡献" aria-label="Permalink to &quot;关键贡献&quot;">​</a></h5><ul><li><strong>CPU 核心绑定策略</strong>：开发工具支持将 <code>reactor</code> 绑定到指定 CPU 核心，优化 OSD 分布。</li><li><strong>I/O 成本评估工具</strong>：基于硬件能力提供性能指标，使用 <code>pandas</code> 分析数据并生成报告。</li><li><strong>Messenger 性能分析</strong>：对比 Crimson 异步 <code>messenger</code> 与 Classic 同步 <code>messenger</code>，发现 16 核心为性能拐点，高并发下存在资源争用。</li><li><strong>自动化测试工具</strong>：为 SEF 基准测试工具开发回归测试生成器，确保代码变更不影响基线性能。</li></ul><h4 id="未来计划与优化方向" tabindex="-1">未来计划与优化方向 <a class="header-anchor" href="#未来计划与优化方向" aria-label="Permalink to &quot;未来计划与优化方向&quot;">​</a></h4><ul><li><strong>Crimson 深度优化</strong>：分析 <code>coroutines</code> 在 <code>seastar</code> 中的执行效率，减少 <code>messenger</code> 路径的延迟。</li><li><strong>遗留代码改进</strong>：探索 Classic 代码的潜在优化点。</li><li><strong>社区协作</strong>：呼吁开发者参与性能分析工具链的扩展。</li></ul><h4 id="行动项" tabindex="-1">行动项 <a class="header-anchor" href="#行动项" aria-label="Permalink to &quot;行动项&quot;">​</a></h4><ul><li>完善 <code>reactor</code> 绑定策略对 AMD 的支持</li><li>提交 <code>messenger</code> 资源争用分析报告</li><li>集成实时监控工具到 Crimson 测试框架</li></ul><h4 id="备注" tabindex="-1">备注 <a class="header-anchor" href="#备注" aria-label="Permalink to &quot;备注&quot;">​</a></h4><ul><li>保留关键词：Crimson、seastar、reactor、PG、OSD、messenger、coroutines、NUMA、IOPS。</li></ul><p><strong>会议结束</strong></p>',16)])])}const h=a(t,[["render",l]]);export{m as __pageData,h as default};
